82	        // Handle API exceptions with JSON responses
83	        $exceptions->render(function (Throwable $e, Request $request) {
84	            // Only handle API routes
85	            if (! $request->is('api/*')) {
86	                return null;
87	            }
88	
89	            $response = null;
90	
91	            // Validation errors (422)
92	            if ($e instanceof ValidationException) {
93	                $response = response()->json([
94	                    'message' => 'Validation failed',
95	                    'errors' => $e->errors(),
96	                ], 422);
97	            }
98	
99	            // Model not found (404)
100	            elseif ($e instanceof ModelNotFoundException) {
101	                $response = response()->json([
102	                    'message' => 'Resource not found',
103	                ], 404);
104	            }
105	
106	            // Route not found (404)
107	            elseif ($e instanceof NotFoundHttpException) {
108	                $response = response()->json([
109	                    'message' => 'Endpoint not found',
110	                ], 404);
111	            }
112	
113	            // Policy denials via prepareException() — AuthorizationException(hasStatus=true)
114	            // becomes HttpException(status). denyAsNotFound() → HttpException(404), distinct
115	            // from NotFoundHttpException (route not found). denyWithStatus(423) → HttpException(423).
116	            elseif ($e instanceof HttpException
117	                && ! $e instanceof NotFoundHttpException
118	                && ($e->getStatusCode() === 404 || $e->getStatusCode() === 423)
119	            ) {
120	                $response = $e->getStatusCode() === 404
121	                    ? response()->json(['message' => 'Resource not found'], 404)
122	                    : response()->json(['message' => $e->getMessage() ?: 'Account is pending deletion.'], 423);
123	            }
124	
125	            // Forbidden (403)
126	            elseif ($e instanceof AccessDeniedHttpException) {
127	                \Illuminate\Support\Facades\Log::warning('Access denied', [
128	                    'path' => $request->path(),
129	                    'message' => $e->getMessage(),
130	                ]);
131	
132	                $response = response()->json([
133	                    'message' => $e->getMessage() ?: 'Access denied',
134	                ], 403);
135	            }
136	
137	            // Preserve explicit response exceptions (e.g. throttle 429)
138	            elseif ($e instanceof HttpResponseException) {
139	                $response = $e->getResponse();
140	            }
141	
142	            // Generic error handling
143	            else {
144	                $statusCode = 500;
145	                if ($e instanceof HttpException) {
146	                    $statusCode = $e->getStatusCode();
147	                }
148	
149	                // Log full exception for debugging even in production
150	                if ($statusCode >= 500) {
151	                    \Illuminate\Support\Facades\Log::error('API Error', [
152	                        'exception' => $e,
153	                        'status' => $statusCode,
154	                    ]);
155	                }
156	
157	                // Don't expose internal errors in production
158	                $message = config('app.debug')
159	                    ? $e->getMessage()
160	                    : 'An error occurred';
161	
162	                $response = response()->json([
163	                    'message' => $message,
164	                ], $statusCode);
165	            }
