84	
85	        if ($existing !== '') {
86	            foreach (explode(',', $existing) as $token) {
87	                $trimmed = trim($token);
88	                if ($trimmed !== '') {
89	                    $varyMap[strtolower($trimmed)] = $trimmed;
90	                }
91	            }
92	        }
