5	use Closure;
6	use Illuminate\Http\Request;
7	use Symfony\Component\HttpFoundation\Response;
8	
9	// V2: Security headers on all responses (XFO, CSP, HSTS in production, nosniff, referrer-policy, permissions-policy).
10	class SecureHeaders
11	{
12	    public function handle(Request $request, Closure $next): Response
13	    {
14	        $response = $next($request);
15	
16	        // CORS: always allow any origin. HandleCors middleware normally adds this
17	        // but Laravel Cloud's edge proxy can strip it on some responses. Setting it
18	        // here (global, appended last) guarantees the header survives.
19	        if (! $response->headers->has('Access-Control-Allow-Origin')) {
20	            $response->headers->set('Access-Control-Allow-Origin', '*');
21	        }
22	
23	        $response->headers->set('X-Frame-Options', 'DENY');
24	        $response->headers->set('X-Content-Type-Options', 'nosniff');
25	        $response->headers->set('Referrer-Policy', 'strict-origin-when-cross-origin');
26	        $response->headers->set('Permissions-Policy', 'camera=(), microphone=(), geolocation=()');
27	        $response->headers->set('Content-Security-Policy', "default-src 'none'; frame-ancestors 'none'");
28	
29	        if (! app()->environment('local', 'testing')) {
30	            $response->headers->set('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
31	        }
32	
33	        return $response;
34	    }
35	}
